mapper.select:
SELECT COUNT(*)
FROM pattern_executions pe
JOIN financial_patterns fp
  ON fp.financial_pattern_id = pe.financial_pattern_id
WHERE fp.user_id = #{userId}
  AND pe.pattern_execution_id = #{patternExecutionId}
  AND pe.source_bank_account_id = #{sourceAccountId}
  AND pe.status = 'STARTED'

mapper.update:
UPDATE bank_accounts
SET balance = balance - #{amount}
WHERE user_id = #{userId}
  AND bank_account_id = #{accountId}
  AND registered_person_id IS NULL
  AND balance >= #{amount}

UPDATE pattern_executions
SET status = 'COMPLETED',
    ended_at = #{endedAt}
WHERE pattern_execution_id = #{patternExecutionId}
  AND status = 'STARTED'
